package br.com.tapeteskalke.service; import br.com.tapeteskalke.dto.PermissionDtos.UpdateRequest; import br.com.tapeteskalke.exception.BusinessException; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PermissionAdminService { private final JdbcTemplate jdbc; private final CurrentRole role; public PermissionAdminService(JdbcTemplate jdbc,CurrentRole role){this.jdbc=jdbc;this.role=role;} @Transactional public void update(UpdateRequest r){if(!"DONO".equals(role.value()))throw new BusinessException("ACESSO_NEGADO","Somente o dono pode editar permissões",HttpStatus.FORBIDDEN);var cargos=new HashSet<>(jdbc.queryForList("select codigo from cargo",String.class));apply(r.pages(),"permissao_pagina","pagina",PermissionService.PAGES,cargos);apply(r.actions(),"permissao_acao","acao",PermissionService.ACTIONS,cargos);}
 // table/column vêm só das constantes acima; cargo e permissão são validados contra listas conhecidas antes do SQL.
 private void apply(Map<String,Boolean> values,String table,String column,List<String> known,Set<String> cargos){if(values==null)return;for(var e:values.entrySet()){var key=e.getKey().split(":",2);if(key.length!=2)throw invalid("Use a chave CARGO:permissao");if(!cargos.contains(key[0]))throw invalid("Cargo desconhecido: "+key[0]);if(!known.contains(key[1]))throw invalid("Permissão desconhecida: "+key[1]);if(e.getValue()==null)throw invalid("Valor ausente para "+e.getKey());if("DONO".equals(key[0])&&!e.getValue()&&(key[1].equals("configuracoes")||key[1].equals("configuracoes_editar")))throw new BusinessException("SELF_LOCKOUT","Não é permitido remover o acesso de configuração do DONO",HttpStatus.CONFLICT);int updated=jdbc.update("update "+table+" set permitido=? where cargo_codigo=? and "+column+"=?",e.getValue(),key[0],key[1]);if(updated==0)jdbc.update("insert into "+table+"(cargo_codigo,"+column+",permitido) values (?,?,?)",key[0],key[1],e.getValue());}}
 // Matriz completa (todos os cargos) para a tela de edição; chaves no mesmo formato CARGO:permissao do update.
 @Transactional(readOnly=true) public Map<String,Object> matrix(){requireOwner();var cargos=jdbc.queryForList("select codigo from cargo order by case codigo when 'DONO' then 1 when 'GERENTE' then 2 when 'VENDEDOR' then 3 when 'ESTOQUISTA' then 4 else 5 end",String.class);var pages=new LinkedHashMap<String,Boolean>();jdbc.query("select cargo_codigo,pagina,permitido from permissao_pagina",rs->{pages.put(rs.getString(1)+":"+rs.getString(2),rs.getBoolean(3));});var actions=new LinkedHashMap<String,Boolean>();jdbc.query("select cargo_codigo,acao,permitido from permissao_acao",rs->{actions.put(rs.getString(1)+":"+rs.getString(2),rs.getBoolean(3));});return Map.of("cargos",cargos,"paginas",PermissionService.PAGES,"acoes",PermissionService.ACTIONS,"pages",pages,"actions",actions);}
 private void requireOwner(){if(!"DONO".equals(role.value()))throw new BusinessException("ACESSO_NEGADO","Somente o dono pode editar permissões",HttpStatus.FORBIDDEN);}
 private BusinessException invalid(String message){return new BusinessException("PERMISSAO_INVALIDA",message,HttpStatus.UNPROCESSABLE_ENTITY);}
}
